r('R21','bruma_felix','bruma_amira','amistad_y_confianza','Amira encontró un dato de temperatura oculto por Félix en un lote.','La confianza se sostiene con registros y retiro de producto, no con exigirle creer otra promesa.',False,'V_bruma_felix')
